 private void init(){int vs=0,fs=0,p=0;try{vs=shader(GL_VERTEX_SHADER,"#version 330\nlayout(location=0)in vec3 position;layout(location=1)in vec3 normal;layout(location=2)in vec2 uv;uniform mat4 mount,projection;out vec2 tex;out vec3 n;void main(){gl_Position=projection*mount*vec4(position,1);n=mat3(transpose(inverse(mount)))*normal;tex=uv;}");fs=shader(GL_FRAGMENT_SHADER,"#version 330\nin vec2 tex;in vec3 n;uniform sampler2D sceneDepth,packArt;uniform vec2 outputSize,artEnd;uniform vec4 art;out vec4 colour;void main(){float d=texture(sceneDepth,gl_FragCoord.xy/outputSize).r;if(gl_FragCoord.z>d+.00002)discard;vec2 uv=art.xy+tex*art.zw;if(any(lessThan(uv,art.xy))||any(greaterThan(uv,artEnd)))discard;vec4 surface=texture(packArt,uv);if(surface.a<.1)discard;float light=.72+.28*abs(dot(normalize(n),normalize(vec3(.3,.8,.4))));colour=vec4(surface.rgb*light,surface.a);}");p=glCreateProgram();glAttachShader(p,vs);glAttachShader(p,fs);glLinkProgram(p);if(glGetProgrami(p,GL_LINK_STATUS)==0)throw new IllegalStateException(glGetProgramInfoLog(p));vao=glGenVertexArrays();vbo=glGenBuffers();glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,vbo);for(int a=0;a<3;a++)glEnableVertexAttribArray(a);glVertexAttribPointer(0,3,GL_FLOAT,false,32,0L);glVertexAttribPointer(1,3,GL_FLOAT,false,32,12L);glVertexAttribPointer(2,2,GL_FLOAT,false,32,24L);depthSampler=glGenSamplers();artSampler=glGenSamplers();for(int s:new int[]{depthSampler,artSampler}){glSamplerParameteri(s,GL_TEXTURE_MIN_FILTER,s==depthSampler?GL_NEAREST:GL_LINEAR);glSamplerParameteri(s,GL_TEXTURE_MAG_FILTER,s==depthSampler?GL_NEAREST:GL_LINEAR);glSamplerParameteri(s,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glSamplerParameteri(s,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glSamplerParameteri(s,GL_TEXTURE_COMPARE_MODE,GL_NONE);}program=p;p=0;}catch(RuntimeException|LinkageError failed){close();throw failed;}finally{if(vs!=0)glDeleteShader(vs);if(fs!=0)glDeleteShader(fs);if(p!=0)glDeleteProgram(p);}}
